-- Run as the application schema owner before starting with --spring.profiles.active=oracle.
CREATE TABLE customers (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(120) NOT NULL, email VARCHAR2(150) NOT NULL UNIQUE, mobile_number VARCHAR2(20) NOT NULL, pan_number VARCHAR2(10) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE staff_users (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR2(80) NOT NULL UNIQUE, password VARCHAR2(100) NOT NULL, full_name VARCHAR2(120) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE customer_users (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR2(80) NOT NULL UNIQUE, password VARCHAR2(100) NOT NULL, avatar_key VARCHAR2(32) DEFAULT 'mosaic-fox' NOT NULL, customer_id NUMBER NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_customer_user_customer FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE gateway_payment_orders (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL, card_id NUMBER NOT NULL, gateway_order_id VARCHAR2(100) NOT NULL UNIQUE, gateway_payment_id VARCHAR2(100), amount NUMBER(15,2) NOT NULL, status VARCHAR2(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_gateway_payment_customer FOREIGN KEY (customer_id) REFERENCES customers(id), CONSTRAINT fk_gateway_payment_card FOREIGN KEY (card_id) REFERENCES credit_cards(id));
CREATE TABLE credit_cards (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL, card_number VARCHAR2(19) NOT NULL UNIQUE, card_type VARCHAR2(20) NOT NULL, credit_limit NUMBER(15,2) NOT NULL, available_credit NUMBER(15,2) NOT NULL, outstanding_amount NUMBER(15,2) NOT NULL, expiry_date DATE NOT NULL, status VARCHAR2(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_card_customer FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE merchants (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(120) NOT NULL, category VARCHAR2(80) NOT NULL, location VARCHAR2(120) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE transactions (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, card_id NUMBER NOT NULL, merchant_id NUMBER NULL, amount NUMBER(15,2) NOT NULL, transaction_type VARCHAR2(20) NOT NULL, status VARCHAR2(20) NOT NULL, failure_reason VARCHAR2(500), transaction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_tx_card FOREIGN KEY (card_id) REFERENCES credit_cards(id), CONSTRAINT fk_tx_merchant FOREIGN KEY (merchant_id) REFERENCES merchants(id));
CREATE TABLE monthly_statements (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL, card_id NUMBER NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, opening_balance NUMBER(15,2) NOT NULL, purchases NUMBER(15,2) NOT NULL, payments NUMBER(15,2) NOT NULL, closing_balance NUMBER(15,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT uq_statement UNIQUE(card_id, period_start), CONSTRAINT fk_stmt_customer FOREIGN KEY (customer_id) REFERENCES customers(id), CONSTRAINT fk_stmt_card FOREIGN KEY (card_id) REFERENCES credit_cards(id));
CREATE INDEX idx_gateway_payment_customer ON gateway_payment_orders(customer_id); CREATE INDEX idx_gateway_payment_status ON gateway_payment_orders(status); CREATE INDEX idx_card_customer ON credit_cards(customer_id); CREATE INDEX idx_tx_card_date ON transactions(card_id, transaction_date); CREATE INDEX idx_tx_merchant ON transactions(merchant_id); CREATE INDEX idx_statement_customer ON monthly_statements(customer_id);
